class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        n = len(t)
        if n > len(s):
            return 0
        dp = [0] * (n + 1)   # dp[j] = ways to form t[:j] from the prefix of s seen so far
        dp[0] = 1            # the empty target is formed exactly once
        for ch in s:
            for j in range(n, 0, -1):   # downward so dp[j-1] is still from the previous prefix
                if t[j - 1] == ch:
                    dp[j] += dp[j - 1]
        return dp[n]

